export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { z } from 'zod'
import db from '@/lib/db'
import { getMpesaService } from '@/lib/payments/mpesa'
import { getPlan, getTotalPrice } from '@/lib/subscription/catalog'
import { resolveSeatSelection } from '@/lib/subscription/seatSelection'
import { logger } from '@/lib/logger'

// AUTO-GENERATED by api-row-sweep --apply — REVIEW these column types.
// pg returns bigint/numeric as string, timestamptz as Date; add `| null` where nullable.
interface PaymentIntentRow {
  id: string
}

// AUDIT FIX (C4, 2026-07-02):
//   - Removed columns (amount_kes, purpose, reference_id) that don't exist
//     in payment_intents table
//   - Added plan_id column (added via migration 026)
//   - Pass callbackUrl with paymentId + planId query params so the
//     callback can look up the payment intent without relying on
//     CheckoutRequestID-only matching

const InitiateSchema = z.object({
  // Kept optional for older callers, but never trusted as the charge source.
  amount: z.number().positive().optional(),
  phoneNumber: z.string().min(10),
  planId: z.enum(['free', 'pro', 'team', 'firm', 'enterprise']).default('free'),
  seatCount: z.number().int().optional(),
  purpose: z.string().max(200).optional(),
  referenceId: z.string().max(200).optional(),
  currency: z.string().length(3).default('KES'),
})

export const POST = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 }, schema: InitiateSchema },
  async (_req, ctx) => {
    const { amount: submittedAmount, phoneNumber, planId, seatCount: requestedSeatCount, purpose, referenceId, currency } = ctx.body as z.infer<
      typeof InitiateSchema
    >

    if (currency !== 'KES') {
      return NextResponse.json({ error: 'M-Pesa STK Push is available in KES only.' }, { status: 400 })
    }

    const seatSelection = resolveSeatSelection(planId, requestedSeatCount)
    if (!seatSelection.ok) return NextResponse.json({ error: seatSelection.error }, { status: 400 })
    const plan = getPlan(planId)
    if (!plan || plan.contactSales) {
      return NextResponse.json({ error: 'This plan is not available through self-serve checkout.' }, { status: 400 })
    }
    const amount = getTotalPrice(planId, 'KES', seatSelection.totalSeats)
    if (!Number.isFinite(amount) || amount <= 0) {
      return NextResponse.json({ error: 'This plan has no M-Pesa checkout price.' }, { status: 400 })
    }
    if (submittedAmount !== undefined && Math.round(submittedAmount * 100) !== Math.round(amount * 100)) {
      return NextResponse.json({ error: 'The submitted amount does not match the current plan price.' }, { status: 400 })
    }

    const mpesa = getMpesaService()
    if (!mpesa) return NextResponse.json({ error: 'M-Pesa is not configured.' }, { status: 503 })

    // 1. Create payment intent with the correct columns
    const paymentResult = await db.query<PaymentIntentRow>(
      `INSERT INTO payment_intents
         (user_id, amount, currency, payment_method, status, plan_id, metadata)
       VALUES ($1, $2, $3, 'mpesa', 'pending', $4, $5)
       RETURNING id`,
      [
        ctx.userId,
        amount,
        currency,
        planId,
        JSON.stringify({ purpose, referenceId, seatCount: seatSelection.totalSeats, extraSeats: seatSelection.extraSeats }),
      ]
    )

    if (paymentResult.rows.length === 0) {
      return NextResponse.json({ error: 'Failed to create payment' }, { status: 500 })
    }

    const paymentIntentId = paymentResult.rows[0].id

    // 2. Build callback URL with paymentId + planId as query params.
    //    Safaricom preserves query params when POSTing to the CallBackURL,
    //    so the callback route can look up the payment intent directly.
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000'
    const callbackUrl = `${appUrl}/api/payments/mpesa/callback?paymentId=${encodeURIComponent(
      paymentIntentId
    )}&planId=${encodeURIComponent(planId)}`

    try {
      const mpesaResponse = await mpesa.initiateSTKPush({
        phoneNumber,
        amount,
        reference: `METARDU-${paymentIntentId.slice(0, 8)}`,
        description: purpose || 'METARDU subscription',
        callbackUrl,
      })

      // 3. Update payment intent with provider ref + processing status
      await db.query<never>(
        `UPDATE payment_intents
         SET checkout_request_id = $1, status = 'processing', updated_at = NOW()
         WHERE id = $2`,
        [mpesaResponse.checkoutRequestId, paymentIntentId]
      )

      return NextResponse.json({
        paymentIntentId,
        checkoutRequestId: mpesaResponse.checkoutRequestId,
      })
    } catch (mpesaError) {
      logger.error('M-Pesa error:', { error: mpesaError })

      await db.query<never>(
        `UPDATE payment_intents SET status = 'failed', updated_at = NOW() WHERE id = $1`,
        [paymentIntentId]
      )

      return NextResponse.json(
        {
          error:
            mpesaError instanceof Error ? mpesaError.message : 'M-Pesa payment failed',
        },
        { status: 500 }
      )
    }
  }
)
